#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * QuickSort - A recursive implementation of the QuickSort algorithm.
 * 
 * This implementation uses the "partition" technique to divide the array
 * into two subarrays: one containing elements smaller than the pivot,
 * and one containing elements larger than the pivot.
 * 
 * Time Complexity: O(n log n) on average
 * Space Complexity: O(log n) for the recursion stack (in-place partitioning)
 * 
 * Note: This implementation does not use heap allocation or dynamic arrays.
 * It uses a fixed-size array for the partitioning.
 */

void quicksort(int arr[], int left, int right) {
    /* Base case: if the array has only one element, it's already sorted */
    if (left >= right) {
        return;
    }

    /* Choose a pivot element */
    int pivot = arr[left];

    /* Partition the array around the pivot */
    int i = left;
    int j = right;

    /* Move elements smaller than pivot to smaller indices */
    while (i < j) {
        /* Move elements larger than pivot to larger indices */
        if (arr[i] < pivot) {
            i++;
        } else if (arr[i] > pivot) {
            j--;
        }
    }

    /* Swap pivot with the element at the partition point */
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;

    /* Recursively sort the left and right subarrays */
    quicksort(arr, left, i - 1);
    quicksort(arr, i + 1, right);
}

/*
 * Example usage:
 * 
 * int main() {
 *     int arr[] = {3, 2, 1, 4, 5, 6};
 *     quicksort(arr, 0, 5);
 *     printf("Sorted array: ");
 *     for (int i = 0; i < 6; i++) {
 *         printf("%d ", arr[i]);
 *     }
 *     printf("\n");
 *     return 0;
 * }
 */

int main() {
    int arr[] = {3, 2, 1, 4, 5, 6};
    quicksort(arr, 0, 5);

    printf("Sorted array: ");
    for (int i = 0; i < 6; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}
```

### Key Features of This Implementation:

1. **Recursive Structure**: The `quicksort` function is recursive, dividing the array into smaller subarrays until they are sorted.
2. **Partitioning**: The `partition` function uses two pointers (`i` and `j`) to find the correct pivot position.
3. **Swapping**: The pivot is swapped with the element at the partition point to ensure the pivot is in its correct sorted position.
4. **Base Case**: The base case handles the case where the array has only one element, preventing infinite recursion.
5. **In-Place Partitioning**: The implementation uses a fixed-size array for the partitioning, which is efficient for small arrays.

